entries[77067] = { ["name"] = "Reins of the Blazing Drake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Blazing Drake mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Blazing Drakes exhibit a boundless passion for life, and are considered by many to be among the most loyal mounts on Azeroth.\"\nDrop:\nElementium Fragment\nLocation:\nDragon Soul" }
entries[77068] = { ["name"] = "Reins of the Twilight Harbinger", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Twilight Harbinger mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Whatever dark magic once compelled the Twilight Harbinger is now broken... or is it?\"\nAchievement:\nGlory of the Dragon Soul Raider\nCategory:\nDungeons & Raids" }
entries[77069] = { ["name"] = "Life-Binder's Handmaiden", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Life-Binder's Handmaiden. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Alexstrasza, the former dragon Aspect of Life, is known to be a kind and patient mentor. Under her tutelage, only the most dedicated pupils acquire the title of \"Life-Binder's Handmaiden.\"\"\nDrop:\nElementium Fragment\nLocation:\nDragon Soul" }
